  return flight::make_ref<RenderEffectPadding>(RenderEffectPadding{.bottom = std::ceil((gaussian->bottom + flight::maximum(0.0, dy))), .left = std::ceil((gaussian->left + flight::maximum(0.0, -dx))), .right = std::ceil((gaussian->right + flight::maximum(0.0, dx))), .top = std::ceil((gaussian->top + flight::maximum(0.0, -dy)))});
